	}

	db := testutil.NewTestDB(nil)

	switch os.Args[1] {
	case "send":
		err := runSendCommand(db)
		if err != nil {
			log.Fatalf("send command failed: %v", err)
		}
	case "list":
		err := runListCommand(db)
		if err != nil {
			log.Fatalf("list command failed: %v", err)
		}
	case "archive":
		err := runArchiveCommand(db)
		if err != nil {
			log.Fatalf("archive command failed: %v", err)
		}
	case "watch":
		err := runWatchCommand(db)
		if err != nil {
			log.Fatalf("watch command failed: %v", err)
		}
	default:
		log.Fatalf("Unknown command: %s", os.Args[1])
	}
}

func run(args []string, db *gorm.DB) error {
	flagSet := flag.NewFlagSet("csuite-inbox", flag.ContinueOnError)

	// Common flags for all commands
	help := flagSet.Bool("help", false, "Show help")

	if err := flagSet.Parse(args); err != nil {
		return err
	}

	if *help {
		flagSet.Usage()
		return nil
	}

	return nil
}

func runSendCommand(db *gorm.DB) error {
	from := flag.String("from", "", "Message sender")
	to := flag.String("to", "", "Message recipient")
	subject := flag.String("subject", "", "Message subject")
	priority := flag.String("priority", "normal", "Message priority (low, normal, high)")
	msgType := flag.String("type", "message", "Message type (message, request, notification)")
	body := flag.String("body", "", "Message body")

	flag.Parse()

	if *from == "" {
		return fmt.Errorf("required flag --from is missing")
	}

	// Create message using the inbox package
	msg := &inbox.Message{
		From:     *from,
		To:       *to,
		Subject:  *subject,
		Priority: *priority,
		Type:     *msgType,
		Body:     *body,
	}

	// Save to database
	result := db.Create(msg)
	if result.Error != nil {
		return result.Error
	}

	fmt.Printf("Message sent successfully with ID: %s\n", msg.ID)
	return nil
}

func runListCommand(db *gorm.DB) error {
	agent := flag.String("agent", "", "Agent name to list messages for")

	flag.Parse()

	if *agent == "" {
		return fmt.Errorf("required flag --agent is missing")
	}

	// List unread messages for agent
	var messages []inbox.Message
	result := db.Where("to = ? AND archived = ?", *agent, false).Find(&messages)
	if result.Error != nil {
		return result.Error
	}

	for _, msg := range messages {
		fmt.Printf("ID: %s | From: %s | Subject: %s | Priority: %s | Type: %s\n",
			msg.ID, msg.From, msg.Subject, msg.Priority, msg.Type)
	}

	return nil
}

func runArchiveCommand(db *gorm.DB) error {
	id := flag.String("id", "", "Message ID to archive")

	flag.Parse()

	if *id == "" {
		return fmt.Errorf("required flag --id is missing")
	}

	// Archive message by ID
	result := db.Model(&inbox.Message{}).Where("id = ?", *id).Update("archived", true)
	if result.Error != nil {
		return result.Error
	}

	fmt.Printf("Message with ID %s archived successfully\n", *id)
	return nil
}

func runWatchCommand(db *gorm.DB) error {
	agent := flag.String("agent", "", "Agent name to watch")

	flag.Parse()

	if *agent == "" {
