func TestSendCommand_CreatesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)

	// Run the send command with required flags
	args := []string{
		"send",
		"--from", "kyle",
		"--to", "alex",
		"--subject", "Test",
		"--priority", "high",
		"--type", "request",
		"--body", "Hello",
	}

	err := run(args, db)
	if err != nil {
		t.Fatalf("run failed: %v", err)
	}

	// Verify message was created in DB with correct fields
	var message inbox.Message
	result := db.First(&message)
	if result.Error != nil {
		t.Fatalf("failed to find message: %v", result.Error)
	}

	if message.From != "kyle" {
		t.Errorf("expected From='kyle', got '%s'", message.From)
	}

	if message.To != "alex" {
		t.Errorf("expected To='alex', got '%s'", message.To)
	}

	if message.Subject != "Test" {
		t.Errorf("expected Subject='Test', got '%s'", message.Subject)
	}

	if message.Priority != "high" {
		t.Errorf("expected Priority='high', got '%s'", message.Priority)
	}

	if message.Type != "request" {
