	To        string    `gorm:"not null"`
	Subject   string    `gorm:"not null"`
	Body      string
	Priority  string    `gorm:"not null;default:normal"`
	Type      string    `gorm:"not null;default:message"`
	Archived  bool      `gorm:"default:false"`
	CreatedAt time.Time
	UpdatedAt time.Time
}"}

